    title: "Electric Vehicle Driving Licence India: Do You Need a Special Licence for EV?",
    description:
      "Do you need a different driving licence to drive an EV in India? The rules for Ola S1, Tata Nexon EV, and electric two-wheelers — explained clearly.",
    category: "Licence Guide",
    readTime: 4,
